&lt;h2&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;About&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;AlayaCare&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;276295ed-5df2-5456-988c-5fdbab071054|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Aptos&amp;quot;,469777842,&amp;quot;&amp;quot;,469777843,&amp;quot;Aptos&amp;quot;,469777844,&amp;quot;Aptos&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Aptos&amp;quot;,268442635,&amp;quot;24&amp;quot;,335559739,&amp;quot;180&amp;quot;,335559738,&amp;quot;180&amp;quot;,469775450,&amp;quot;First Paragraph&amp;quot;,201340122,&amp;quot;2&amp;quot;,134234082,&amp;quot;true&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;FirstParagraph&amp;quot;,335572020,&amp;quot;1&amp;quot;,469775498,&amp;quot;Body Text&amp;quot;,469778324,&amp;quot;Body Text&amp;quot;]}&quot;&gt;At&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;AlayaCare&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;we’re&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;more than just a fast-growing SaaS&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;company,&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;we’re&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;a team of people passionate about transforming home healthcare. Our cloud-based platform empowers care providers around the world to deliver better outcomes for their clients. With 600+ employees across Canada, the US, Australia, and Brazil,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;we’re&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;united by a shared mission and a strong culture of transparency, growth, and human connection. Whether you’re early in your career or a seasoned expert,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;AlayaCare&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;offers the opportunity to grow your impact, your skills, and your career.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:180,&amp;quot;335559739&amp;quot;:180}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;About the Role&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;The Professional Services Consultant plays a critical, customer-&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;facing&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;and internal role that enables the growth of professional services. In this role, you will&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;be responsible for&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;the successful delivery and execution of professional services-led implementations and projects. You will lead customer and internal stakeholders, apply subject matter&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;expertise&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;in the&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;AlayaCare&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;platform and the home care industry, and help customers achieve value through high-quality project deliverables.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:180,&amp;quot;335559739&amp;quot;:180}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:180,&amp;quot;335559739&amp;quot;:180}&quot;&gt;This position will focus on customers located in the United States, with a focus on skilled care and Infusion.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;What&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;You’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;&amp;nbsp;Do&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;eafb41c0-47a4-52dc-ac6b-3b5a7536b560|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Aptos&amp;quot;,469777842,&amp;quot;&amp;quot;,469777843,&amp;quot;Aptos&amp;quot;,469777844,&amp;quot;Aptos&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Aptos&amp;quot;,268442635,&amp;quot;24&amp;quot;,335559739,&amp;quot;36&amp;quot;,335559738,&amp;quot;36&amp;quot;,469775450,&amp;quot;Compact&amp;quot;,201340122,&amp;quot;2&amp;quot;,134234082,&amp;quot;true&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;Compact&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Body Text&amp;quot;]}&quot;&gt;Lead project teams through&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;requirements&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;&amp;nbsp;gathering, workflow design, configuration, reporting, testing, and user training.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Serve as a trusted advisor to customers, addressing issues as they arise and escalating to the Project Manager when scope, timeline, or budget may be&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;impacted&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Support customers through digital transformation across all aspects of their home care operations.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Partner with Account Managers to ensure a smooth transition for customers exiting the stabilization phase of their customer journey.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Contribute to the development of repeatable professional services offerings and packages.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Deliver data-driven consulting recommendations based on industry and segment best practices.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Develop customer testing and training plans, iterate on&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;AlayaCare&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;&amp;nbsp;best practices, and support execution of the Professional Services Delivery Model.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Identify&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;&amp;nbsp;new Professional Services opportunities with existing customers and collaborate with senior team members to define and present proposals.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Support Implementation Specialists in learning the product and market and in delivering quality engagements.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Provide input into the development of new professional services offerings.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Offer ongoing coaching to Implementation Specialists on assigned projects, including documenting feedback for their managers.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Maintain up-to-date knowledge of and compliance with internal processes and procedures.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Perform other job-related duties as assigned.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;What You Bring&lt;/span&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;5+ years of relevant professional experience.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Bachelor’s Degree (B.Sc.,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;B.Comm&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;., or equivalent).&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;3+ years of experience in SaaS consulting and/or health care implementations.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;2+ years of experience leading complex internal and external engagements, including functional and cross-functional teams.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Demonstrated passion for understanding customer business goals and challenges.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Ability to communicate effectively with customer leadership.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Proven ability to recognize and clearly articulate complex project-related problems.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Deep&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;expertise&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;&amp;nbsp;in the&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;AlayaCare&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;&amp;nbsp;platform and/or relevant functional areas.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:36,&amp;quot;335559739&amp;quot;:36}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Compact&quot;&gt;Willingness and ability to travel and work weekends as required (go-lives are scheduled for weekends).&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;Location and Work Model&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;This role is remote but requires candidates to be authorized to work in, as well as physically located in, the United States. The role requires consistent travel to visit customers on site (about 10-15%), as well as occasional weekend work for go-lives.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;Why Join&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;AlayaCare&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;?&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;Work With Purpose&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:80,&amp;quot;335559739&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;At&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;AlayaCare&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;you’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;help build technology that empowers care providers and improves outcomes for patients and families. Every customer interaction contributes to making care more connected, accessible, and human.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:180,&amp;quot;335559739&amp;quot;:180}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;Grow in a High-Trust Culture&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:80,&amp;quot;335559739&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;We believe in transparency, feedback, and assuming positive intent. Here,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;you’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;&amp;nbsp;feel safe to share your ideas and career goals, and be supported to achieve them through mentorship, career mobility, and a promote-from-within philosophy.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:180,&amp;quot;335559739&amp;quot;:180}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;Balance That Works for You&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:80,&amp;quot;335559739&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
